let pointer={x:0,y:0},pourAt=null,selected=[],memories=[],index=0,texture=null,pouring=false;
function resize(){const mobile=innerWidth<=760;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.fov=38;camera.position.set(0,mobile?6.9:5.7,mobile?10.7:8.4);camera.lookAt(0,1.5,0);camera.setViewOffset(innerWidth,innerHeight,mobile?0:-innerWidth*.16,mobile?innerHeight*.02:0,innerWidth,innerHeight);camera.updateProjectionMatrix()}resize();addEventListener('resize',resize);addEventListener('pointermove',e=>{pointer.x=e.clientX/innerWidth-.5;pointer.y=e.clientY/innerHeight-.5});
const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const t=clock.getElapsedTime();if(!$('#memory-view').hidden&&!entering)return;let diving=diveAt===null?0:Math.min((t-diveAt)/1.55,1);if(diving){const smooth=diving*diving*(3-2*diving),mobile=innerWidth<=760;camera.position.set(0,THREE.MathUtils.lerp(mobile?6.9:5.7,2.5,smooth),THREE.MathUtils.lerp(mobile?10.7:8.4,1.4,smooth));camera.lookAt(0,THREE.MathUtils.lerp(1.5,1.87,smooth),0);camera.setViewOffset(innerWidth,innerHeight,(mobile?0:-innerWidth*.16)*(1-smooth),0,innerWidth,innerHeight);camera.fov=38+smooth*17;camera.updateProjectionMatrix();}magic.update(t,{pourProgress:pourAt===null?null:Math.min((t-pourAt)/4.8,1),hasSelection:selected.length>0||pouring,dive:diving});waterUniforms.time.value=reduced?0:t;stars.rotation.y=reduced?0:t*.012;pool.rotation.y+=(pointer.x*.15-pool.rotation.y)*.02;if(pourAt!==null){const elapsed=t-pourAt,progress=Math.min(elapsed/4.8,1);wand.visible=progress<.84;wand.position.y=3.75+Math.sin(progress*Math.PI)*.2;threadMat.opacity=Math.sin(progress*Math.PI);for(let i=0;i<threadCount;i++){const f=i/threadCount;const q=(f+t*.23)%1;const y=3.75-q*1.88;const radius=.025+q*q*.38;threadPos[i*3]=.65*(1-q)+Math.sin(q*16-t*4)*radius;threadPos[i*3+1]=y;threadPos[i*3+2]=.25*(1-q)+Math.cos(q*16-t*4)*radius}threadGeo.attributes.position.needsUpdate=true;waterUniforms.power.value=Math.sin(progress*Math.PI)*.75;ripple.scale.setScalar(.1+(elapsed%1.5)/1.5*1.5);rippleMat.opacity=(1-(elapsed%1.5)/1.5)*.35;if(progress>.5)waterUniforms.hasPhoto.value=Math.min((progress-.5)*2,1);if(progress>=1){pourAt=null;threadMat.opacity=0;rippleMat.opacity=0;waterUniforms.power.value=0;finishPour()}}renderer.render(scene,camera)}frame();
function discard(list){list.forEach(p=>URL.revokeObjectURL(p.url))}
async function selectFiles(files){if(pouring)return;const valid=[...files].filter(f=>f.type.startsWith('image/'));if(!valid.length){$('#status').textContent='请选择 JPG、PNG、WebP 等照片文件';return}const decoded=[];for(const file of valid.slice(0,20)){const url=URL.createObjectURL(file);const img=new Image();img.src=url;try{await img.decode();decoded.push({url,name:file.name,img})}catch{URL.revokeObjectURL(url)}}if(!decoded.length){$('#status').textContent='这些照片暂时无法读取，请尝试 JPG 或 PNG 格式';return}discard(selected);selected=decoded;$('#selection').hidden=false;$('#thumb').src=selected[0].url;$('#filename').textContent=selected[0].name;$('#count').textContent=`已选择 ${selected.length} 张照片`;$('#pour').disabled=false;$('#status').textContent=valid.length>20?'已选取前 20 张照片，每次最多注入 20 张':'准备好了，把这一刻交给水面';$('#photos').value=''}
$('#photos').addEventListener('change',e=>selectFiles(e.target.files));$('#clear').onclick=()=>{if(pouring)return;discard(selected);selected=[];$('#selection').hidden=true;$('#thumb').removeAttribute('src');$('#pour').disabled=true;$('#status').textContent='重新选择一段记忆'};
const drop=$('#drop');for(const type of ['dragenter','dragover'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('drag')});for(const type of ['dragleave','drop'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.remove('drag')});drop.addEventListener('drop',e=>selectFiles(e.dataTransfer.files));
$('#pour').onclick=()=>{if(!selected.length||pouring)return;pouring=true;playRitualSound('pour');$('#pour').disabled=true;$('#photos').disabled=true;$('#clear').disabled=true;$('#enter').hidden=true;$('#status').textContent='记忆正在化作银丝，落入水中…';$('#pool-title').textContent='A MEMORY TAKES SHAPE';if(texture)texture.dispose();texture=new THREE.Texture(selected[0].img);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;waterUniforms.photo.value=texture;waterUniforms.aspect.value=selected[0].img.width/selected[0].img.height;waterUniforms.hasPhoto.value=0;if(reduced){waterUniforms.hasPhoto.value=1;finishPour()}else pourAt=clock.getElapsedTime()};
function finishPour(){memories.push(...selected);index=memories.length-selected.length;selected=[];pouring=false;$('#selection').hidden=true;$('#thumb').removeAttribute('src');$('#photos').disabled=false;$('#clear').disabled=false;$('#status').textContent='记忆已入水。触碰水面，重返那一刻。';$('#pool-title').textContent='YOUR MEMORY LIVES HERE';$('#pool-hint').textContent='每一次凝视，都是一次重逢';$('#memory-total').textContent=`已珍藏 ${memories.length} 段记忆 · 本次会话`;$('#enter').hidden=false;renderShelf()}
function showPhoto(){$('#delete-status').textContent='';const m=memories[index];displayMemory(m);$('#memory-photo').src=m.url;$('#memory-photo').alt=m.name;$('#memory-index').textContent=`${String(index+1).padStart(2,'0')} / ${String(memories.length).padStart(2,'0')}`;$('#prev').disabled=memories.length<2;$('#next').disabled=memories.length<2;renderShelf()}
function enterMemory(){if(!memories.length||pouring||entering||!$('#memory-view').hidden)return;entering=true;playRitualSound('enter');$('#enter').disabled=true;diveAt=clock.getElapsedTime();document.body.classList.add('is-diving');setTimeout(()=>{$('#memory-view').hidden=false;document.body.classList.remove('is-diving');document.body.classList.add('in-memory');showPhoto();$('#close').focus();entering=false;},reduced?0:1550)}$('#enter').onclick=enterMemory;$('#close').onclick=()=>{$('#memory-view').hidden=true;document.body.classList.remove('in-memory');stopModelView();diveAt=null;entering=false;$('#enter').disabled=false;resize();$('#enter').focus()};$('#prev').onclick=()=>{index=(index-1+memories.length)%memories.length;showPhoto()};$('#next').onclick=()=>{index=(index+1)%memories.length;showPhoto()};
addEventListener('keydown',e=>{if($('#memory-view').hidden)return;if(e.key==='Escape')$('#close').click();if(e.key==='ArrowLeft')$('#prev').click();if(e.key==='ArrowRight')$('#next').click();if(e.key==='Tab'){const focusable=[...$('#memory-view').querySelectorAll('button,a[href],summary,input,select,[tabindex]')].filter(el=>!el.disabled&&el.getClientRects().length);let i=focusable.indexOf(document.activeElement);e.preventDefault();focusable[(i+(e.shiftKey?-1:1)+focusable.length)%focusable.length].focus()}});
const raycaster=new THREE.Raycaster();$('#scene').addEventListener('click',e=>{raycaster.setFromCamera(new THREE.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);if(raycaster.intersectObject(water).length)enterMemory()});
let audioContext,gain;$('#sound').onclick=async()=>{try{if(!audioContext){audioContext=new AudioContext();gain=audioContext.createGain();gain.gain.value=.025;gain.connect(audioContext.destination);for(const freq of [146.83,220,293.66]){const osc=audioContext.createOscillator();osc.type='sine';osc.frequency.value=freq;osc.connect(gain);osc.start()}}if(audioContext.state==='running'&&$('#sound').getAttribute('aria-pressed')==='true'){await audioContext.suspend();$('#sound').setAttribute('aria-pressed','false');$('#sound span').textContent='环境音关闭';$('#sound').setAttribute('aria-label','开启水池环境音')}else{await audioContext.resume();$('#sound').setAttribute('aria-pressed','true');$('#sound span').textContent='环境音开启';$('#sound').setAttribute('aria-label','关闭水池环境音')}}catch{$('#status').textContent='此浏览器暂不支持环境音'}};
addEventListener('pagehide',()=>{discard(selected);discard(memories);texture?.dispose();audioContext?.close()});

loadSavedMemories().then(saved=>{if(!saved.length)return;memories.push(...saved);if(memories.length===saved.length){index=Math.max(0,memories.findLastIndex(x=>x.status==='ready'));const latest=memories[index];texture=new THREE.Texture(latest.img);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;waterUniforms.photo.value=texture;waterUniforms.aspect.value=latest.img.width/latest.img.height;waterUniforms.hasPhoto.value=1;$('#enter').hidden=false;$('#pool-title').textContent='YOUR MEMORY LIVES HERE';$('#pool-hint').textContent='触碰水面，进入你的 3D 记忆';$('#status').textContent='已找回这台电脑上保存的记忆';}$('#memory-total').textContent=`已收藏 ${memories.length} 段记忆`;renderShelf();}).catch(()=>{$('#status').textContent='本地照片模式可用，AHOLO 服务暂未连接';});

function renderShelf(){const shelf=$('#memory-shelf');shelf.replaceChildren();shelf.hidden=!memories.length;memories.forEach((m,i)=>{const button=document.createElement('button');button.className='memory-fragment'+(i===index?' is-active':'');button.title=m.name;button.setAttribute('aria-label',`选择记忆：${m.name}`);button.setAttribute('aria-pressed',String(i===index));const img=document.createElement('img');img.src=m.url;img.alt='';const mark=document.createElement('span');mark.textContent=m.id&&m.status!=='ready'?'凝成中':m.mode==='world'?'空间':m.model_url?'物件':'原片';button.append(img,mark);button.onclick=()=>{if(pouring||entering)return;index=i;if(texture)texture.dispose();texture=new THREE.Texture(m.img);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;waterUniforms.photo.value=texture;waterUniforms.aspect.value=m.img.width/m.img.height;waterUniforms.hasPhoto.value=1;$('#pool-hint').textContent=m.name;renderShelf();};shelf.append(button);});}
if(!reduced)addEventListener('pointermove',e=>{if($('#memory-view').hidden||$('#memory-photo').hidden)return;const x=(e.clientX/innerWidth-.5)*6,y=(e.clientY/innerHeight-.5)*-5;$('#memory-photo').style.transform=`perspective(1200px) rotateX(${y}deg) rotateY(${x}deg) translateZ(12px)`;});

function playRitualSound(kind){if(!audioContext||audioContext.state!=='running')return;const t=audioContext.currentTime,voice=audioContext.createGain();voice.gain.setValueAtTime(.0001,t);voice.gain.exponentialRampToValueAtTime(kind==='pour'?.035:.025,t+.15);voice.gain.exponentialRampToValueAtTime(.0001,t+1.6);voice.connect(audioContext.destination);for(const [i,f] of (kind==='pour'?[659.25,987.77,1318.5]:[220,329.63,440]).entries()){const o=audioContext.createOscillator();o.type='sine';o.frequency.setValueAtTime(f,t+i*.08);o.frequency.exponentialRampToValueAtTime(f*(kind==='enter'?.5:1.015),t+1.5);o.connect(voice);o.start(t+i*.08);o.stop(t+1.7);}}

let deleting=false;
$('#delete-memory').onclick=async()=>{
 const m=memories[index];
 if(!m||deleting)return;
 if(!confirm(`删除“${m.name||'这段记忆'}”？本机保存的照片、模型和地点标记将一并删除，无法撤销。已使用的生成额度不会返还。`))return;
 deleting=true;$('#delete-memory').disabled=true;
 try{
  await deleteMemory(m);
  const removed=memories.indexOf(m);memories.splice(removed,1);discard([m]);
  index=Math.min(index,Math.max(0,memories.length-1));
  texture?.dispose();texture=null;waterUniforms.photo.value=null;
  if(memories.length){
   const next=memories[index];texture=new THREE.Texture(next.img);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;
   waterUniforms.photo.value=texture;waterUniforms.aspect.value=next.img.width/next.img.height;waterUniforms.hasPhoto.value=1;
   $('#pool-hint').textContent=next.name;showPhoto();
  }else{
   $('#close').click();waterUniforms.hasPhoto.value=0;$('#enter').hidden=true;
   $('#memory-photo').removeAttribute('src');$('#pool-title').textContent='THE WATER REMEMBERS';$('#pool-hint').textContent='移动光标，凝视水面';$('#photos').focus();
  }
  $('#memory-total').textContent=memories.length?`已收藏 ${memories.length} 段记忆`:'尚未存入记忆';
  $('#status').textContent='记忆已删除';renderShelf();
 }catch(e){$('#delete-status').textContent=e.message;}
 finally{deleting=false;$('#delete-memory').disabled=false;}
};
